CREATE TYPE "public"."shift_check_status" AS ENUM('matched', 'pending', 'approved', 'rejected');
CREATE TABLE "shiftCheckItems" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "shiftCheckItems_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"shiftCheckId" integer NOT NULL,
	"ingredientId" integer NOT NULL,
	"ingredientName" varchar(180) NOT NULL,
	"unit" varchar(40) NOT NULL,
	"openingQuantity" numeric(14, 3) NOT NULL,
	"purchaseQuantity" numeric(14, 3) NOT NULL,
	"usageQuantity" numeric(14, 3) NOT NULL,
	"otherQuantity" numeric(14, 3) NOT NULL,
	"systemQuantity" numeric(14, 3) NOT NULL,
	"countedQuantity" numeric(14, 3) NOT NULL,
	"variance" numeric(14, 3) NOT NULL,
	"costPerUnit" numeric(14, 2) NOT NULL
);

CREATE TABLE "shiftCheckPhotos" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "shiftCheckPhotos_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"shiftCheckId" integer NOT NULL,
	"storageKey" varchar(512) NOT NULL,
	"contentType" varchar(64) NOT NULL,
	"byteSize" integer NOT NULL
);

CREATE TABLE "shiftChecks" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "shiftChecks_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"reference" varchar(64) NOT NULL,
	"status" "shift_check_status" NOT NULL,
	"submittedByUserId" integer NOT NULL,
	"submittedByName" varchar(120) NOT NULL,
	"note" text,
	"shiftStartedAt" timestamp (0) with time zone NOT NULL,
	"varianceItemCount" integer NOT NULL,
	"totalVarianceValue" numeric(14, 2) NOT NULL,
	"saleCount" integer NOT NULL,
	"grossSales" numeric(14, 2) NOT NULL,
	"voidRefundValue" numeric(14, 2) NOT NULL,
	"netSales" numeric(14, 2) NOT NULL,
	"openingCash" numeric(14, 2) NOT NULL,
	"countedCash" numeric(14, 2) NOT NULL,
	"countedNonCash" numeric(14, 2) NOT NULL,
	"incomeVariance" numeric(14, 2) NOT NULL,
	"submittedAt" timestamp (0) with time zone DEFAULT now() NOT NULL,
	"reviewedByUserId" integer,
	"reviewedByName" varchar(120),
	"reviewNote" text,
	"reviewedAt" timestamp (0) with time zone,
	CONSTRAINT "shiftChecks_reference_unique" UNIQUE("reference")
);

ALTER TABLE "businessSettings" ADD COLUMN "shiftOpeningCash" numeric(14, 2) DEFAULT 0 NOT NULL;
ALTER TABLE "ingredients" ADD COLUMN "shiftCheck" boolean DEFAULT false NOT NULL;
ALTER TABLE "shiftCheckItems" ADD CONSTRAINT "shiftCheckItems_shiftCheckId_shiftChecks_id_fk" FOREIGN KEY ("shiftCheckId") REFERENCES "public"."shiftChecks"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "shiftCheckItems" ADD CONSTRAINT "shiftCheckItems_ingredientId_ingredients_id_fk" FOREIGN KEY ("ingredientId") REFERENCES "public"."ingredients"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "shiftCheckPhotos" ADD CONSTRAINT "shiftCheckPhotos_shiftCheckId_shiftChecks_id_fk" FOREIGN KEY ("shiftCheckId") REFERENCES "public"."shiftChecks"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "shiftChecks" ADD CONSTRAINT "shiftChecks_submittedByUserId_users_id_fk" FOREIGN KEY ("submittedByUserId") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "shiftChecks" ADD CONSTRAINT "shiftChecks_reviewedByUserId_users_id_fk" FOREIGN KEY ("reviewedByUserId") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;
CREATE INDEX "shift_check_items_check_idx" ON "shiftCheckItems" USING btree ("shiftCheckId");
CREATE INDEX "shift_check_photos_check_idx" ON "shiftCheckPhotos" USING btree ("shiftCheckId");
CREATE INDEX "shift_checks_status_idx" ON "shiftChecks" USING btree ("status","submittedAt");
CREATE INDEX "shift_checks_submitter_idx" ON "shiftChecks" USING btree ("submittedByUserId","submittedAt");
-- Block Supabase Data API access (see 0001_enable_rls.sql); the app connects as the table owner.
ALTER TABLE "shiftChecks" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "shiftCheckItems" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "shiftCheckPhotos" ENABLE ROW LEVEL SECURITY;
